      step('Choose protection and priority', 20, ['Select five assets for urgent attention. Cite the inventory item.', 'Score legal certainty, business value and urgency separately. High uncertainty is a reason to investigate, not a prediction of invalidity.'], [table('priority', 'Five priority actions', [col('asset', 'Asset / evidence ID'), col('certainty', 'Legal certainty 1–5', 'score'), col('value', 'Business value 1–5', 'score'), col('urgency', 'Urgency 1–5', 'score'), col('route', 'Protection route and reason')], Array.from({length: 5}, () => ({})))], 'Five reasoned priorities, including a secrecy or ownership control.'),
      step('Resolve ownership and disclosure gaps', 20, ['Draft an instruction for the freelancer assignment and a contributor schedule for the manual.', 'Explain the effect of the casing disclosure as an investigation question under the relevant national law.'], [text('ownership', 'Ownership remediation brief', 'Specify background IP, deliverables, rights to transfer, signatures and evidence to retain.'), text('disclosure', 'Patent/design and confidentiality investigation', 'Identify disclosure date, territories, any grace-period question, registry checks and immediate controls.')], 'A practical evidence request and a disclosure-risk plan.'),
      step('Set the licence position', 20, ['Choose an opening position for A10 and explain what could be traded.', 'Separate code access for continuity from ownership transfer.'], [table('licence', 'Six-point distributor position', [col('topic', 'Term', 'fixed'), col('opening', 'Opening position'), col('fallback', 'Fallback and approval condition')], ['Exclusivity', 'Territory / duration', 'Object code / escrow', 'Fee / royalty and audit', 'Sublicensing', 'Milestones / termination'].map(topic => ({topic})))], 'A six-point licence brief ready for the negotiation workshop.'),
      step('Commit the 90-day plan', 15, ['Allocate the 100 planning units across the five priorities; state the total.', 'Name owners, evidence of completion and review dates. Export the register.'], [text('plan', '90-day remediation plan', 'Use 0–30 / 31–60 / 61–90 days; include five actions, owners, budget units and success evidence.'), text('decision', 'Board recommendation', 'State which distributor discussions may proceed and which rights need confirmation first.')], 'An auditable register, ownership-gap list and prioritised action plan.')
