  labs.push({
    id: 'licence-negotiation', number: 2, day: 1, module: 2, title: 'Technology Licence Negotiation', subtitle: 'Turn an unbalanced term sheet into a workable deal.', method: 'Negotiation role-play', minutes: 120, icon: '02',
    scenario: 'Meridian’s venture DrukLex Solutions owns a contract-analysis product. Sengri Systems wants to distribute it to banks and public bodies. Work individually first, then negotiate with a partner. Both role briefs are available for this educational role-play.',
    objectives: ['Define licence scope, background IP and improvements.', 'Negotiate risk, economics and exit as a connected package.', 'Record agreed language and matters requiring approval.'], carry: 'Export the negotiated term sheet. Reuse its audit, liability and exit structure on Days 2 and 4.', sources: ['bhutan', 'wipo'],
    documents: [
      doc('LIC-01', 'Proposed term sheet', 'C1 All improvements created by either party belong exclusively to Sengri.\nC2 DrukLex grants an irrevocable worldwide licence for any purpose.\nC3 Sengri may appoint any sublicensee without notice.\nC4 Sengri is exclusive across South Asia for ten years.\nC5 Royalty is 4% of net revenue, calculated by Sengri.\nC6 One audit only, at DrukLex cost, on 60 days’ notice.\nC7 Confidentiality ends after two years.\nC8 DrukLex warrants uninterrupted and error-free operation.\nC9 DrukLex is liable for all indirect loss without limit.\nC10 Sengri may terminate at any time; DrukLex may not terminate.\nC11 Source code and all technical know-how are delivered on signing.'),
      doc('LIC-02', 'DrukLex role brief', 'Protect background IP and keep ownership of the core platform. You can offer a 12-month Bhutan pilot and conditional exclusivity. You need verifiable royalty records and termination for non-payment. Your insurer has not approved an unlimited liability promise. Escrow may address continuity, but access conditions and cost need agreement.'),
      doc('LIC-03', 'Sengri role brief', 'You will invest 30 planning units in customer onboarding. You want a reasonable opportunity to recover that cost, product support and continuity if DrukLex fails. You can accept field-limited rights and equivalent sublicense terms. You need written service and remedy commitments, not a promise of perfect software.'),
      doc('LIC-04', 'Business sponsor instructions', 'Do not agree tax treatment, public-procurement eligibility or governing-law enforceability without advice. The term sheet is subject to final contract, finance approval and legal approval. Record concessions explicitly. A walk-away with reasons is an acceptable outcome.')
    ],
    steps: [
      step('Prepare your mandate', 15, ['Read both role briefs; choose the role you will represent.', 'Carry forward any unresolved ownership assumptions from Lab 1. Define five priorities before negotiating.'], [text('role', 'Your role', '', 'select', ['DrukLex counsel', 'Sengri counsel', 'Solo reviewer of both positions']), text('mandate', 'Five priorities and approval limits', 'List opening position, minimum acceptable outcome and matters outside your authority.')], 'A clear mandate, including a reasoned walk-away position.'),
      step('Review all eleven terms', 25, ['Rate and decide a position on each clause in LIC-01.', 'Use exact clause IDs; explain consequences for the party you represent.'], [table('clauses', 'Clause review', clauseColumns, Array.from({length: 11}, (_, i) => ({ id: 'C' + (i + 1) })))], 'An eleven-row review with proposed wording or a documented fallback.'),
      step('Draft the priority protections', 30, ['Draft replacement wording for C1, C2, C4, C6, C8 and C10.', 'Use scope limits, measurable obligations, remedies and balanced termination. Avoid a universal liability formula.'], [text('redlines', 'Six replacement clauses', 'Label each clause. Cover background IP, permitted use, conditional exclusivity, records/audit, realistic warranty/remedy and termination/transition.'), text('continuity', 'Source-code continuity mechanism', 'Define escrow deposit/update duties, release events, permitted use, costs and security.')], 'Six reviewable replacements and a continuity solution.'),
      step('Negotiate and record concessions', 30, ['Discuss four priority clauses with a partner; solo learners write a counterproposal for each.', 'Record each side’s concession and the approval still needed. Do not mark a point agreed if unresolved.'], [table('negotiation', 'Negotiation record', [col('topic', 'Clause / topic'), col('offer', 'Opening / counteroffer'), col('outcome', 'Agreed wording or unresolved issue'), col('approval', 'Approval owner / next action')], Array.from({length: 4}, () => ({})))], 'A term sheet that clearly separates agreement from open issues.'),
      step('Advise the sponsor', 20, ['Explain the deal in five sentences: value, remaining exposure, dependency, approval and next step.', 'Export your record and prepare a two-minute explanation.'], [text('sponsor', 'Sponsor recommendation', 'Proceed, proceed conditionally or walk away; identify unresolved issues and the specific authority needed.')], 'A negotiated term sheet and a concise approval brief.')
    ],
    checks: [quiz('Why revise “worldwide, any purpose”?', ['It always invalidates a contract', 'It may exceed the intended product, field and territory', 'It proves ownership'], 1, 'Scope should match the commercial rights intended; enforceability is a separate legal question.'), quiz('Who should usually remain contractually accountable for sublicensees?', ['The main licensee under agreed flow-down terms', 'Nobody', 'Every end user without a contract'], 0, 'Written flow-down protections and continuing licensee responsibility make the chain manageable.'), quiz('Which is a more workable software commitment?', ['Absolute perfection', 'No remedy under any circumstances', 'Material conformity to agreed specifications with defined remedies'], 2, 'Testable performance and proportionate remedies make a promise useful.')],
    debrief: ['Background IP, new developments and licence rights are different concepts.', 'Define net revenue, evidence rights and remedies together.', 'An unapproved deal is not improved by labelling it agreed.'], rubric: ['All eleven clauses reviewed', 'Six redrafts contain operational detail', 'Four concessions and approval conditions recorded', 'Recommendation explains remaining exposure']
  });
  labs.push({
    id: 'verified-ai-review', number: 3, day: 2, module: 3, title: 'Verified AI Legal Review', subtitle: 'Summarise, extract, compare and verify against the source.', method: 'Guided practice', minutes: 150, icon: '03',
    scenario: 'Meridian is reviewing a fictional NorthStar SaaS agreement. Practise the Upload → Summarise → Flag → Draft pattern using an approved AI tool, or use the supplied simulated output if no tool is available. Every finding must be checked by you.',
    objectives: ['Write a Goal–Context–Source–Expectations prompt.', 'Extract obligations and compare clauses with exact references.', 'Identify hallucinations, preserve review boundaries and draft a verified memo.'], carry: 'Use the verified issue table as your evidence discipline in Lab 4.', sources: ['ai', 'nistai'],
    documents: [
      doc('AI-01', 'NorthStar agreement v1', 'C1 Service: contract repository and AI-assisted summaries; no autonomous signature authority.\nC2 Fees: USD 24,000/year.\nC3 Renewal: automatic for one year unless customer gives notice 60 days before renewal.\nC4 Data: customer retains rights in uploaded material. Vendor may use inputs and outputs to improve any products.\nC5 Incidents: vendor notifies customer within 48 hours after becoming aware of a security incident affecting customer data.\nC6 Availability: 99.5% monthly; service credits are the only availability remedy.\nC7 Liability: aggregate liability limited to fees paid in the preceding six months; no IP infringement indemnity.\nC8 Termination: vendor may terminate for convenience on 30 days’ notice; customer has no matching right.\nC9 Exit: customer must export before termination; no transition assistance.\nC10 Support: customer nominates a service owner before activation.'),
      doc('AI-02', 'Meridian review playbook', 'P1 No use of customer inputs or outputs for model training or unrelated product improvement without specific written approval.\nP2 Renewal owner must record and review notice dates.\nP3 Seek mutual termination and usable export/transition provisions.\nP4 Seek appropriate IP protection and a liability structure proportionate to exposure; finance and legal must approve the final allocation.\nP5 Legal conclusions and externally shared drafts require qualified human review.\nP6 AI-generated citations are leads; verify the primary source, date and applicability.'),
      doc('AI-03', 'Simulated AI output — intentionally unreliable', '1. The vendor provides an IP infringement indemnity under C7.\n2. The agreement renews automatically unless notice is given 30 days before renewal (C3).\n3. Vendor may use customer material for product improvement (C4).\n4. The agreement gives both sides equal termination rights (C8).\n5. There is a 99.5% monthly availability commitment (C6).\n6. Bhutan’s “AI Liability Act 2026” requires a USD 5 million cap. No source supplied.\nThis is simulated practice content, not a live model response.'),
      doc('AI-04', 'eDiscovery mini-set — synthetic', 'E1: Procurement asks Legal to check the C4 training permission.\nE2: Counsel’s legal advice to management, marked confidential; privilege status requires lawyer assessment.\nE3: Duplicate of E1 with an attachment missing.\nE4: Unrelated lunch invitation.\nPreserve document IDs. Tag potentially privileged material for restricted review; do not infer privilege from a label alone.'),
      doc('AI-05', 'Prompt sheet', 'Goal: prepare an internal review, not a final approval. Context: Meridian is the customer. Sources: AI-01 and AI-02 only. Expectations: return clause ID, exact wording, issue, proposed fix, owner and uncertainty. Do not invent clauses, deadlines, law or facts.\nVerification: Validate facts; Examine evidence; Review permissions; Inspect impact; Fit the audience; retain Your accountability (VERIFY).')
    ],
    steps: [
      step('Choose a safe workflow and prompt', 20, ['Use only the fictional source documents. Choose an approved AI service or the supplied offline simulation.', 'Write the full prompt with goal, customer role, source boundaries, output schema and verification instruction.'], [text('mode', 'Practice mode', '', 'select', ['Approved external AI tool', 'Supplied simulated output — offline']), text('prompt', 'Your review prompt', 'Use AI-05 as a structure; identify exactly which files and clauses the assistant may use.')], 'A reusable prompt with explicit source and review boundaries.'),
      step('Extract and compare', 35, ['Read AI-01 yourself before reviewing generated output.', 'Extract four operational obligations. Record relative notice periods without inventing calendar dates.', 'Compare C4, C7, C8 and C9 to the playbook.'], [table('obligations', 'Obligation matrix', [col('id', 'Clause ID'), col('obligation', 'Exact obligation / trigger'), col('owner', 'Owner / person to confirm'), col('deadline', 'Deadline / missing date'), col('evidence', 'Evidence of completion')], Array.from({length: 4}, () => ({}))), table('comparison', 'Deviation table', [col('clause', 'Clause', 'fixed'), col('rule', 'Playbook ID'), col('difference', 'Verified deviation'), col('fix', 'Proposed fix and approval')], ['C4', 'C7', 'C8', 'C9'].map(clause => ({clause})))], 'An obligation matrix and a verified four-clause deviation table.'),
      step('Audit the simulated claims', 35, ['Test all six claims in AI-03 against the contract and playbook.', 'Quote the clause or state “no supplied authority”. For claim 6, build a primary-source research plan instead of repeating the invented statute.'], [table('claims', 'Verification log', [col('claim', 'AI-03 claim', 'fixed'), col('verdict', 'Result', 'select', ['Supported', 'Incorrect', 'Unsupported / needs research']), col('proof', 'Source ID and correction')], Array.from({length: 6}, (_, i) => ({claim: 'Claim ' + (i + 1)}))), text('research', 'Research plan for claim 6', 'List the legal question, jurisdiction, official source, date/version check and facts needed. No invented citation.')], 'A corrected claim log that prevents unsupported legal advice.'),
      step('Triage review material and tool limits', 25, ['Tag each eDiscovery item without deleting evidence.', 'Explain why prediction scores and agentic actions need additional validation, permission controls and human approval.'], [table('discovery', 'eDiscovery triage', [col('id', 'Item', 'fixed'), col('tag', 'Tag', 'select', ['Relevant', 'Potential privilege — restrict', 'Duplicate — preserve/link', 'Not relevant — retain under protocol']), col('reason', 'Reason / next reviewer')], ['E1', 'E2', 'E3', 'E4'].map(id => ({id}))), text('limits', 'Predictive / agentic safeguards', 'Address test data, error costs, permissions, action approval, audit trail and failure handling.')], 'A traceable document triage and a human-control boundary.'),
      step('Draft the verified review memo', 35, ['Draft a 200–300 word internal memo with the three highest priorities, evidence and questions for Procurement/Security.', 'Apply VERIFY. Record what you changed from the AI output. Export your work.'], [text('memo', 'Verified internal memo', 'Use exact clause IDs; distinguish text, inference, unknown fact and legal research question.'), text('verify', 'VERIFY audit note', 'Record one check for each of the six VERIFY elements and name the final approval role.')], 'A fact-checked review memo and a reusable verification process.')
    ],
    checks: [quiz('What is C3’s actual renewal notice period?', ['30 days', '60 days', '48 hours'], 1, 'C3 states 60 days before renewal; the renewal date is not supplied.'), quiz('How should the invented statute in AI-03 be handled?', ['Repeat it if it sounds plausible', 'Replace it with another unverified citation', 'Label unsupported and check official legislation'], 2, 'The source pack supplies no such authority. A research plan is safer than a fabricated conclusion.'), quiz('Does a “confidential” label prove legal privilege?', ['No; a qualified reviewer must assess the communication and applicable law', 'Yes, always', 'Only if generated by AI'], 0, 'Privilege depends on legal tests and facts, not just a label.')],
    debrief: ['AI-03 claims 1, 2 and 4 conflict with C7, C3 and C8. Claims 3 and 5 are supported. Claim 6 has no supplied authority.', 'Source-restricted extraction and legal research are different tasks.', 'Manual review is a full practice route when an approved AI tool is unavailable.'], rubric: ['Prompt includes four G-C-S-E elements', 'Four obligations and four deviations have source references', 'Six simulated claims independently checked', 'Memo and VERIFY record show human accountability']
  });
  labs.push({
    id: 'ai-procurement', number: 4, day: 2, module: 4, title: 'AI Procurement & Legal Risk', subtitle: 'Classify the use. Negotiate the terms. Set the control.', method: 'Risk-allocation clinic', minutes: 110, icon: '04',
    scenario: 'Meridian’s governance committee must compare TalentPulse HR AI and LexisDraft Legal AI. Follow the sample workbench’s five-question procurement approach. A single “risk tier” or contract cap cannot answer all the legal and operational questions.',
    objectives: ['Assess intended purpose, jurisdiction and organisational role before classification.', 'Allocate data, IP, accuracy, audit and liability risks using evidence.', 'Define deployment conditions, human oversight and an internal usage rule.'], carry: 'Carry the risk register and five redlines into the privacy, cloud and capstone labs.', sources: ['ai', 'oecd', 'bhutan', 'nistai'],
    documents: [
      doc('PROC-01', 'Two vendor fact sheets', 'A — TalentPulse: USD 36,000/year. Ranks job applicants and rejects the lowest-scoring 40% automatically. Pilot includes recruitment by an EU subsidiary. Uses CVs and interview notes. Vendor has not supplied subgroup testing or a meaningful appeal workflow.\nB — LexisDraft: USD 24,000/year. Drafts and reviews ordinary commercial contracts for internal legal staff. No recruitment scoring, court decision assistance or autonomous approval is described. Uses a third-party general-purpose model. “95% accuracy” is claimed without a benchmark definition. Users may upload privileged or confidential text.\nBoth are fictional products. Scope, role and intended deployment must be assessed separately for each.'),
      doc('PROC-02', 'Vendor clauses — both proposals', 'C1 Accuracy: “Outputs are suggestions only; vendor makes no performance commitment.”\nC2 Data: “Vendor may retain prompts and outputs indefinitely and use them to train any models.”\nC3 IP: “Vendor owns all outputs; customer warrants all inputs and indemnifies all third-party claims.”\nC4 Liability: “Vendor liability is capped at one month of fees; customer liability is unlimited.”\nC5 Assurance: “Vendor may change models or subprocessors without notice; audits are prohibited.”\nC6 Oversight: “Customer is solely responsible for every decision; vendor need not provide logs.”\nC7 Exit: “No export or deletion evidence will be provided.”'),
      doc('PROC-03', 'Procurement mandate and evidence gaps', 'No fixed cap has been approved. Security estimates a plausible loss range of USD 250,000–1,000,000 for a significant incident, subject to validation. Insurance limits, exclusions and recovery need checking. Procurement can negotiate general caps, specific higher caps, remedies and tightly defined exclusions; legal enforceability and insurability require review. Do not promise reimbursement of every regulatory fine.\nVendor evidence requested: intended-use statement, performance test design, error rates by relevant group, data flow, retention schedule, subprocessor list, model-change notice, audit/log capability, training-data provenance summary, security evidence, IP defence process and tested export/deletion.'),
      doc('PROC-04', 'Classification and internal-rule guide', 'Step 1: identify territorial scope, intended purpose, actor role and prohibited-use questions. Step 2: examine any high-risk category and applicable exceptions, then transparency obligations. Step 3: assess the separate GPAI model/provider layer. A general legal assistant is not automatically a high-risk justice system or automatically a GPAI provider.\nEU rules are a comparative lens unless their territorial and material scope applies. Bhutan laws, sector rules, contractual duties and governance guidance must be checked separately. GNH is a values lens, not a substitute for identifying binding duties.\nInternal rule: green = approved low-sensitivity drafting with checking; amber = restricted material only in an approved environment with authorisation; red = unapproved sensitive uploads or unsupervised decisions affecting people. These are fictional company controls, not statutory categories.')
    ],
    steps: [
      step('Classify the tool and the use', 20, ['Assess both products against PROC-01 and PROC-04.', 'Distinguish territorial scope, intended use, Meridian’s role and the GPAI model layer. Check current official sources before asserting duties or dates.'], [table('classify', 'Two-use classification memo', [col('tool', 'Tool', 'fixed'), col('scope', 'Territory / actor role'), col('purpose', 'Intended use and provisional category'), col('basis', 'Source / reasoning / unresolved fact')], [{tool: 'TalentPulse'}, {tool: 'LexisDraft'}]), text('classification', 'Committee classification conclusion', 'Explain why HR ranking deserves heightened review and why the legal tool still needs data, accuracy and oversight controls.')], 'A conditional classification memo with a separate local-law check.'),
      step('Check data and IP terms', 25, ['Review C2 and C3 together with the evidence gaps.', 'Separate customer inputs, vendor/model IP and generated outputs. Output assignment alone cannot establish that new copyright exists or eliminate third-party claims.'], [table('dataip', 'Data and IP redline workbench', clauseColumns, [{id: 'C2 Data / training / retention'}, {id: 'C3 Inputs / model / outputs / IP claims'}]), text('evidence', 'Vendor evidence request', 'Ask for five documents or demonstrations, with an owner and acceptance criterion for each.')], 'Two drafted protections plus a testable due-diligence request.'),
      step('Check accuracy, assurance and liability', 25, ['Review C1 and C4–C7. Explain why “95%” is not sufficient evidence.', 'Propose a general cap and any separate treatment using exposure, fees, insurance and remedies. Numbers are commercial assumptions, not legal requirements.'], [table('allocation', 'Risk-allocation register', riskColumns, ['Accuracy / bias', 'Liability / remedy', 'Audit / model changes', 'Human oversight / logs', 'Exit / deletion'].map(topic => ({topic}))), text('liability', 'Liability proposal and rationale', 'Specify assumed exposure, cap basis, any higher cap/exclusions, treatment of fines subject to law, insurance checks and approval owner.')], 'A risk register and a justified negotiation package.'),
      step('Set five redlines and the internal rule', 25, ['Write five must-have positions with fallback and walk-away conditions.', 'Write a one-line usage rule and a control that names who reviews what, when, and with what evidence.'], [table('redlines', 'Five red-line positions', [col('term', 'Protection', 'fixed'), col('wording', 'Proposed contract wording'), col('fallback', 'Fallback / approval condition')], ['Data isolation / no unauthorised training', 'Input-model-output rights / IP defence', 'Measurable quality / audit / change notice', 'Liability and remedies', 'Human review / logs / export and deletion'].map(term => ({term}))), text('policy', 'One-line usage rule', 'Use allowed purpose + restricted data + required review + escalation owner.'), text('oversight', 'Operating control', 'Specify reviewer, sampling or per-output review, logs, approval gates, appeal and stop procedure.')], 'Five usable clauses and an enforceable internal operating rule.'),
      step('Make the committee decision', 15, ['Give a separate decision for each tool; state what would change it.', 'Record three red/amber/green examples under the fictional internal policy.'], [table('approval', 'Deployment decisions', [col('tool', 'Tool', 'fixed'), col('decision', 'Decision', 'select', options.decision), col('conditions', 'Conditions, owner and evidence before use')], [{tool: 'TalentPulse'}, {tool: 'LexisDraft'}]), text('traffic', 'Three internal-policy examples', 'Include one green, one amber and one red example and the applicable review action.')], 'A reasoned approval memo, risk grid, five redlines and one-line policy.')
    ],
    checks: [quiz('What should precede an EU AI Act classification?', ['The vendor’s marketing label', 'Intended use, scope and actor-role assessment', 'The price of the subscription'], 1, 'The facts and applicable legal tests determine the analysis; a product label is insufficient.'), quiz('Is a USD 5 million liability cap always required?', ['Yes', 'Only for legal tools', 'No; it must be justified and negotiated for the exposure'], 2, 'Fees, potential loss, remedies, insurance and applicable law inform the negotiation.'), quiz('Does assigning output rights guarantee new copyright protection?', ['No; existence, ownership and third-party rights still need analysis', 'Yes, in every country', 'Yes, if the vendor says so'], 0, 'Contractual allocation and statutory protection are different questions.')],
    debrief: ['TalentPulse’s recruitment decisions and EU deployment require a specific high-risk analysis; do not assume every AI tool has the same category.', 'LexisDraft’s ordinary drafting purpose does not remove confidentiality, accuracy, professional or contractual risks.', 'The GPAI layer is separate. Avoid universal caps, automatic uncapped fine reimbursement and unsupported competence certificates.'], rubric: ['Both tools assessed with scope and role', 'Data and IP issues separately allocated', 'Risk scoring and liability assumptions explained', 'Five redlines and an operational human-review control', 'Separate conditional deployment decisions']
  });
